(function(){'use strict';
const data=JSON.parse(document.getElementById('page-data').textContent),pages=data.pages,assets=data.assets||{},files=data.files||{},mounts=data.mounts||[];
const article=document.getElementById('article');
const ui=KBUI.start(data);
function normalize(s){let a=[];for(let p of s.split('/')){if(!p||p==='.')continue;if(p==='..'){if(!a.length)return null;a.pop()}else a.push(p)}return a.join('/')}
function resolve(current,href){if(/^(?:[a-z][a-z0-9+.-]*:|\/\/)/i.test(href))return null;let [p,frag]=href.split('#',2);try{p=decodeURIComponent(p.split('?')[0])}catch(e){}let mount=mounts.find(name=>current.startsWith(name+'/'));let base=href.startsWith('/')?(mount&&!p.startsWith('/'+mount+'/')?mount+'/':''):current.substring(0,current.lastIndexOf('/')+1);let key=p===''?current:normalize(base+p.replace(/^\//,''));return key===null?null:{key,frag:frag||''}}
function current(){let h;try{h=decodeURI(location.hash.replace(/^#\/?/,''))}catch(e){h=''}let [p,frag]=h.split('#',2);return {path:pages[p]?p:(pages['README.md']?'README.md':Object.keys(pages).sort()[0]),frag:frag||''}}
function render(){let {path,frag}=current();if(!path){article.textContent='No pages in this bundle';return}let md=pages[path],html=marked.parse(md);article.innerHTML=data.trustHTML?html:DOMPurify.sanitize(html);article.querySelectorAll('a[href],img[src]').forEach(el=>{let attr=el.tagName==='IMG'?'src':'href',href=el.getAttribute(attr),r=resolve(path,href);if(!r)return;if(assets[r.key]){el.setAttribute(attr,assets[r.key]);return}if(files[r.key]){el.setAttribute(attr,files[r.key]);return}if(pages[r.key]){el.setAttribute(attr,'#/'+r.key.split('/').map(encodeURIComponent).join('/')+(r.frag?'#'+r.frag:''));return}if(!href.startsWith('#'))el.removeAttribute(attr)});KBUI.externalLinks(article,data.externalLinksNewTab);article.querySelectorAll('pre code').forEach(el=>{if(el.className.includes('language-mermaid')){let div=document.createElement('div');div.className='mermaid';div.textContent=el.textContent;el.parentElement.replaceWith(div)}else if(window.hljs)hljs.highlightElement(el)});if(window.mermaid){mermaid.run({querySelector:'.mermaid'}).catch(e=>console.error(e))}if(frag)setTimeout(()=>document.getElementById(frag)?.scrollIntoView(),0);document.title=(path.split('/').pop()||data.title)+' — '+data.title;ui.setActive(path)}
window.addEventListener('hashchange',render);render();
})();
